"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[656],{7996(e){e.exports=JSON.parse('{"title":"\uc778\uc9c0 \ubd80\ud558\ub294 \uc5b4\ub514\uc11c \uc624\ub294\uac00","date":"2025-01-05","coverUrl":"/kudzu-based-bench/assets/notion/01c37562f17ebb44.png","html":"<h2 data-notion-block-id=\\"16be548d-8a8e-80b6-b42c-c841f50ccd04\\" id=\\"16be548d-8a8e-80b6-b42c-c841f50ccd04\\">\uc778\uc9c0 \ubd80\ud558\ub294 \uc5b4\ub514\uc11c \uc624\ub294\uac00</h2><a href=\\"https://minds.md/zakirullin/cognitive#long\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://minds.md/zakirullin/cognitive#long</a><p data-notion-block-id=\\"16be548d-8a8e-80af-8219-c9f0ace3a83e\\"><b>\uc2ec\uc724\uc12d</b>: \uae30\uc220 \uad00\ub828 \uae00\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc88b\uc740 \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud574\uc11c \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. \uc778\uc9c0 \ubd80\ud558\ub97c \ud3c9\uc18c \uc77c\uc744 \ud560 \ub54c\ub3c4, \ub2e4\ub978 \ud65c\ub3d9\uc744 \ud560 \ub54c\ub3c4 \uace0\ub824\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc2b5\ub2c8\ub2e4. \uac1c\ubc1c\uc790\uc758 \uc2dc\uc120\uc5d0\uc11c \uc5b4\ub290 \uacbd\uc6b0\uc5d0 \ucf54\ub4dc\uc5d0\uc11c, \ud639\uc740 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc778\uc9c0 \ubd80\ud558\ub97c \ub290\ub07c\uac8c \ub418\ub294\uc9c0\ub97c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubcf4\uc774\uc9c0 \uc54a\ub294 \uc778\uc9c0 \ubd80\ud558\ub97c \ud574\uacb0\ud558\ub294\ub370 \ub3c4\uc6c0\uc774 \ub418\uc5c8\uc73c\uba74 \uc88b\uaca0\ub124\uc694. <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#ec85017c-c8bc-46e1-abbe-e69801686efa\\">\ucd94\uc0c1\ud654\ub294 \uc801\uc808\ud558\uac8c</a>, <a href=\\"https://ones-to-watch.ethansup.net/news/post/fa08117a-8884-4c6c-a884-e39b5c1d607d#80e87956-671b-44f6-a930-7cda0f6394c3\\">\ucd94\uc0c1\ud654\uc640 \uc801\uc808\ud55c \ub808\uc774\uc5b4\uc758 \ucc28\uc774</a>\uc640 \ube44\uc2b7\ud55c \uacb0\uc758 \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><p data-notion-block-id=\\"5cb3ae0c-6c57-41f3-91e8-954482824b64\\"><b>\uae40\ub300\uad00</b>: \uc774\ubc88 \uae00\uc744 \ud1b5\ud574 \uc778\uc9c0 \ubd80\ud558\uac00 \ubb34\uc5c7\uc778\uc9c0, \uadf8\ub9ac\uace0 \uc774\ub97c \uc904\uc774\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc54c \uc218 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ub2e8\uc21c\ud55c \ud504\ub85c\uadf8\ub798\ubc0d \uc6d0\uce59\uc744 \ub530\ub974\ub294 \uac83\uc744 \ub118\uc5b4, \ub0b4\uac00 \uc791\uc131\ud55c \ucf54\ub4dc\uac00 \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uc5b4\ub5bb\uac8c \uc778\uc9c0 \ubd80\ud558\ub97c \uc8fc\ub294\uc9c0 \uace0\ubbfc\ud558\uac8c \ub9cc\ub4dc\ub294 \uc88b\uc740 \uae00\uc774\uc5c8\uc2b5\ub2c8\ub2e4. \uc88b\uc740 \ucf54\ub4dc\uac00 \ubb34\uc5c7\uc778\uc9c0\uc5d0 \ub300\ud574 \uace0\ubbfc\ud558\uace0 \uc788\ub294 \uac1c\ubc1c\uc790\uc5d0\uac8c \ucd94\ucc9c\ud558\uace0 \uc2f6\uc740 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"16be548d-8a8e-809d-ba4d-ce49a5991295\\" id=\\"16be548d-8a8e-809d-ba4d-ce49a5991295\\">JS \ubca4\uce58\ub9c8\ud0b9\uc740 \uc5b4\ub5bb\uac8c \ud574\uc57c \uc815\ud655\ud560\uae4c</h2><a href=\\"https://byteofdev.com/posts/javascript-benchmarking-mess/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://byteofdev.com/posts/javascript-benchmarking-mess/</a><p data-notion-block-id=\\"16be548d-8a8e-805d-b87b-e18f17621121\\"><a href=\\"https://ones-to-watch.ethansup.net/news/post/15ee548d-8a8e-80b5-9d6e-cfa07648afc4#164e548d-8a8e-807b-a6c8-ef1262fcdd25\\">Node.js\ub97c \uacc4\uc18d \uc5c5\ub370\uc774\ud2b8 \ud574\uc57c \ud558\ub294 \uc774\uc720</a>\uc5d0\uc11c\ub3c4 \uc7a0\uae50 \ub098\uc628 \ubca4\uce58\ub9c8\ud06c\ub97c \uc798 \uc124\uc815\ud574\uc57c \ud558\ub294 \uc774\uc720\uc785\ub2c8\ub2e4. JIT \ucef4\ud30c\uc77c\ub7ec(<a href=\\"https://v8.dev/blog/maglev\\">V8\uc774 \ucef4\ud30c\uc77c \ub2e8\uacc4\ub97c \ucd94\uac00\ud558\ub4ef\uc774</a>, \ud56d\uc0c1 \ubc14\ub01d\ub2c8\ub2e4)\uc640 \uc5ec\ub7ec \ucd5c\uc801\ud654 \ubc29\uc2dd(ex. Inline caching)\uc73c\ub85c \uc778\ud574, \ud639\uc740 \ub124\uc774\ud2f0\ube0c \uc2dc\uac04 \uce21\uc815\uc774 \uc815\ud655\ud558\uc9c0 \uc54a\uc544\uc11c\u2026 \ub4f1\ub4f1 \uc5ec\ub7ec \uc774\uc720 \ub54c\ubb38\uc5d0 \ubca4\uce58\ub9c8\ud0b9\uc774 \uc815\ud655\ud558\uc9c0 \uc54a\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc81c\uc5b4\ud560 \ubcc0\uc218\uac00 \ub9ce\uc740 \ub9cc\ud07c, \uc870\uc2ec\ud574\uc11c \uce21\uc815\uc744 \ud574\uc57c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"16be548d-8a8e-805f-b515-e4b56c976f4a\\" id=\\"16be548d-8a8e-805f-b515-e4b56c976f4a\\">\ube44\ubc00\ubc88\ud638\ub294 \uc4f0\ub808\uae30\uc785\ub2c8\ub2e4.</h2><a href=\\"https://www.imperialviolet.org/tourofwebauthn/tourofwebauthn.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.imperialviolet.org/tourofwebauthn/tourofwebauthn.html</a><p data-notion-block-id=\\"16be548d-8a8e-8015-8b82-eb521717e337\\">WebAuthn\uc774 \uc5b4\ub5bb\uac8c \ubc1c\uc804\ud574\uc654\ub294\uc9c0\uc5d0 \ub300\ud55c \uc548\ub0b4\uc11c\uc785\ub2c8\ub2e4. WebAuthn\uc758 \uc5ed\uc0ac, \ub3d9\uc791 \ubc29\uc2dd, \ud50c\ub7ab\ud3fc\ubcc4 \ud2b9\uc9d5\uc744 \ubaa8\ub450 \uc124\uba85\ud569\ub2c8\ub2e4. \uac04\ub2e8\ud558\uac8c \uac1c\uc694\ub9cc \uc54c\uace0 \uc2f6\uc740 \ubd84\uc740 <a href=\\"https://thecopenhagenbook.com/webauthn\\">Copenhagen book\uc758 WebAuthn \ubd80\ubd84</a>\uc744 \ucc38\uace0\ud558\uc138\uc694. WebAuthn\uc744 \ud65c\uc6a9\ud558\uace0\uc790 \ud558\ub294 \ubd84\uc740 \ubaa8\ub450 \uc77d\uc744\ub9cc\ud569\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"16be548d-8a8e-8010-859b-d28f863b6903\\" id=\\"16be548d-8a8e-8010-859b-d28f863b6903\\">RSC\uc640 SPA\uc758 \uc870\ud654\ub97c \uc704\ud55c \uc544\uc774\ub514\uc5b4</h2><a href=\\"https://blog.axlight.com/posts/thoughts-on-what-rsc-means-for-spas/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.axlight.com/posts/thoughts-on-what-rsc-means-for-spas/</a><p data-notion-block-id=\\"16be548d-8a8e-80f5-8eb5-edbdf7622b17\\"><a href=\\"https://react.dev/reference/rsc/server-components\\">\uacf5\uc2dd \ubb38\uc11c\uc5d0\ub3c4 \uc801\ud600\uc788\ub4ef\uc774</a>, Server Components\ub294 SSR\ub97c \uc704\ud55c \uac1c\ub150\uc774 \uc544\ub2d9\ub2c8\ub2e4. \uadf8\ub807\uae30\uc5d0 \ube4c\ub4dc\ud0c0\uc784\uc5d0 \uc0ac\uc6a9\ud560 \uc218\ub3c4 \uc788\uace0(<a href=\\"https://ones-to-watch.ethansup.net/news/post/cd29f440-15b4-4145-a8d4-ec9da1e43ce9#7209e06a-f90c-400f-883b-69e46dbb3b6e\\">Build Time \ud50c\ub7ec\uadf8\uc778 vs RSC</a>), \ud398\uc774\ub85c\ub4dc \uc81c\uacf5\ub9cc\uc744 \uc704\ud55c \uc11c\ubc84\ub97c \uc81c\uacf5\ud560 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc544\uc9c1 \uc544\uc774\ub514\uc5b4\ub9cc\uc744 \uc801\uc5b4\ub193\uc740 \uae00\uc774\uc9c0\ub9cc, \uae00\uc758 \uc800\uc790\uac00 \ub9cc\ub4e0 \ub77c\uc774\ube0c\ub7ec\ub9ac <a href=\\"https://waku.gg/\\">Waku</a>\uac19\uc774 RSC\ub97c \uc11c\ubc84 \uc678\uc5d0\uc11c \uc81c\uacf5\ud558\uae30 \uc704\ud55c \uad6c\ud604\uccb4\uac00 \uc788\uc73c\ub2c8 \ucc3e\uc544\ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"16be548d-8a8e-80af-b4e7-f0c0c03362a5\\" id=\\"16be548d-8a8e-80af-b4e7-f0c0c03362a5\\">\uc0c8\ub85c\uc6b4 \uce5c\uad6c\ub4e4</h2><a href=\\"https://remix.run/blog/react-router-v7\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/react-router-v7</a><a href=\\"https://base-ui.com/react/overview/about\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://base-ui.com/react/overview/about</a><p data-notion-block-id=\\"16be548d-8a8e-8087-85a3-c4b3821a54cf\\">\ub2e4\uc591\ud55c \ud658\uacbd\uc5d0\uc11c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d React Router(Remix) \uc0c8 \ubc84\uc804\uc774 \ub4f1\uc7a5\ud558\uc600\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 Radix UI\ubcf4\ub2e4 \uc801\uadf9\uc801\uc73c\ub85c \uc720\uc9c0\ubcf4\uc218\ud558\uba70 \uac1c\ubc1c\uc790 \uacbd\ud5d8\uc744 \uac1c\uc120\ud558\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc9c4 Base UI(Material UI\uc5d0\uc11c \ub9cc\ub4e6)\uac00 \uc54c\ud30c\ubc84\uc804\uc5d0 \uc774\ub974\ub800\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"172e548d-8a8e-804b-8733-db5461ce6467\\" id=\\"172e548d-8a8e-804b-8733-db5461ce6467\\">\uc554\ud638\ud654 \uae30\ubcf8 \uac1c\ub150 <code>node:crypto</code>\ub97c \ud1b5\ud574 \uc54c\uc544\ubcf4\uae30</h2><a href=\\"https://gitnation.com/contents/mastering-cryptography-fundamentals-with-nodes-crypto-module\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/mastering-cryptography-fundamentals-with-nodes-crypto-module</a><p data-notion-block-id=\\"172e548d-8a8e-80f5-b679-f766e75b3144\\">API \ubb38\uc11c\uac19\uc740 nodejs\ubb38\uc11c \ub300\uc2e0\uc5d0 \uc554\ud638\ud654 \ubaa8\ub4c8\uc758 \uae30\ubcf8 \uac1c\ub150\ub4e4\uc744 \uce5c\uc808\ud558\uac8c \uc124\uba85\ud558\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4. \uc554\ud638\ud654 \ub9d0\uace0 \uc804\uccb4\uc801\uc778 \ubcf4\uc548\uc744 \uc785\ubb38\ud558\ub824\uba74 <a href=\\"https://cheatsheetseries.owasp.org/cheatsheets/Nodejs_Security_Cheat_Sheet.html\\">OWASP NodeJS \ubcf4\uc548 \uce58\ud2b8\uc2dc\ud2b8</a> \ub610\ub294 <a href=\\"https://thecopenhagenbook.com/\\">Copenhagen \ucc45</a>\uc744 \ucc38\uace0\ud558\uc138\uc694.</p><h2 data-notion-block-id=\\"16ce548d-8a8e-8065-b125-d3c0967e1b80\\" id=\\"16ce548d-8a8e-8065-b125-d3c0967e1b80\\">Incremental Build\ub97c \uc704\ud55c \uc5ec\uc815(\uc54c\uace0\ub9ac\uc998 \ubd80\ubd84)</h2><a href=\\"https://gitnation.com/contents/challenges-for-incremental-production-optimizations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://gitnation.com/contents/challenges-for-incremental-production-optimizations</a><p data-notion-block-id=\\"172e548d-8a8e-8049-968e-c29c7544da92\\">Turbopack \uac1c\ubc1c\uc790\uac00 \uc99d\ubd84 \ube4c\ub4dc(Incremental Build)\ub97c \uc704\ud574 \ud504\ub85c\ub355\uc158 \ube4c\ub4dc\uc5d0\uc11c \ud544\uc694\ud55c \ucd5c\uc801\ud654 \uae30\ub2a5\uc774 \uc99d\ubd84 \ube4c\ub4dc\uc640 \ucda9\ub3cc\ud558\ub294 \uc774\uc720\uc640, \uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \uc99d\ubd84 \uc54c\uace0\ub9ac\uc998\uc744 \uc5b4\ub5bb\uac8c \ub9cc\ub4e4\uc5c8\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \ubc1c\ud45c\uc785\ub2c8\ub2e4(\uce90\uc2f1 \ubd80\ubd84\uc5d0 \ub300\ud55c \ub0b4\uc6a9\uc740 \uc5c6\uc74c). \ud504\ub85c\ub355\uc158 \ucd5c\uc801\ud654\ub97c \uc704\ud574 \ubc88\ub4e4\ub7ec\uac00 \ud558\ub294 \uc77c\uacfc \ube4c\ub4dc \uc18d\ub3c4\ub97c \uc704\ud574 \ub9cc\ub4e0 \uc99d\ubd84 \ube4c\ub4dc\uac00 \ubb34\uc5c7\uc778\uc9c0 \uc54c \uc218 \uc788\uc73c\ubbc0\ub85c, \ubc88\ub4e4\ub7ec\uc758 \uc774\ud574\ub97c \uc704\ud574 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p>"}')}}]);